python3 -c 'from pathlib import Path
old="If Hermes is needsAuth or the bridge is missing"
def stage7(path):
    t=Path(path).read_text()
    start=t.index("<stage id=\"7\"")
    end=t.index("</stage>", start)
    return t[start:end]
src=stage7("prompts/bot-00-programming-lead.xml")
need=["user-hermes-agent","agent_bus_health","agent_bus_start_job","agent_bus_get_job","agent_bus_wait_job","Do not SSH the packet as a code handoff","Do not rebuild hermes-mcp-bridge.mjs"]
problems=[]
for f in ("prompts/LEAD.xml","prompts-assembled/LEAD.xml"):
    t=Path(f).read_text()
    if old in t:
        problems.append("obsolete in "+f)
    stage=stage7(f)
    if stage!=src:
        problems.append("stage7 mismatch "+f)
    for n in need:
        if n not in stage:
            problems.append("missing "+n+" in "+f)
print(problems or "ok")
raise SystemExit(0 if not problems else 1)'
